i2,o2=G['Demo pair 2 input'],G['Demo pair 2 output']
i3,o3=G['Demo pair 3 input'],G['Demo pair 3 output']
H,W=len(i1),len(i1[0])
S1=set((i,j) for i in range(H) for j in range(W) if i1[i][j]==2)
def dist(S,dr,dc):
    def d(p):
        d=0; q=p
        while True:
            n=(q[0]+dr,q[1]+dc)
            if not(0<=n[0]<H and 0<=n[1]<W): return None
            if n in S: return d+1
            q=n; d+=1
    return d
for (I,O,S,bg,label) in [(i1,o1,S1,2,'d1'),(i2,o2,set(),5,'d2'),(i3,o3,None,6,'d3')]:
    pass
# do it per-demo generically
def analyze(I,O,H,W,bgv):
    S={(i,j) for i in range(H) for j in range(W) if I[i][j]!=bgv}
    tabs={}
    for i in range(H):
        for j in range(W):
            if I[i][j]!=bgv: continue
            fv=dist(S,-1,0); fb=dist(S,1,0)
            fh=dist(S,0,-1); fr=dist(S,0,1)
            fdl=dist(S,-1,-1); fdr=dist(S,1,1); fdul=dist(S,-1,1); fdur=dist(S,1,-1)
            key=(fv,fb,fh,fr,fdl,fdr,fdul,fdur)
            tabs.setdefault(key,Counter())[O[i][j]]+=1
    return tabs
tab1=analyze(i1,o1,H,W,2)
bad=[k for k,v in tab1.items() if len(v)>1]
print('demo1 conflicting keys:', len(bad))
for k,v in list(tab1.items())[:60]: print(k,dict(v))

